void common(const OpenGLESApi&a,GlUInt p,const RenderFrame&f,const RenderDrawCall&d){auto vp=ul(a,p,"u_view_projection"),m=ul(a,p,"u_model"),c=ul(a,p,"u_camera_position"),amb=ul(a,p,"u_ambient_intensity"),br=ul(a,p,"u_base_roughness"),ms=ul(a,p,"u_metal_specular"),em=ul(a,p,"u_emission_opacity"),ld=ul(a,p,"u_light_direction"),lc=ul(a,p,"u_light_color"),li=ul(a,p,"u_light_intensity");if(vp>=0)a.UniformMatrix4fv(vp,1,0,f.view_projection.m.data());if(m>=0)a.UniformMatrix4fv(m,1,0,d.model.m.data());if(c>=0)a.Uniform3f(c,f.camera.position.x,f.camera.position.y,f.camera.position.z);if(amb>=0)a.Uniform1f(amb,f.lighting.environment.ambient_intensity);const auto&mat=d.material.material;if(br>=0)a.Uniform4f(br,mat.base_color.r,mat.base_color.g,mat.base_color.b,std::clamp(mat.roughness,.045f,1.f));if(ms>=0)a.Uniform4f(ms,std::clamp(mat.metallic,0.f,1.f),mat.specular,0.f,0.f);if(em>=0)a.Uniform4f(em,mat.emission.r,mat.emission.g,mat.emission.b,std::clamp(mat.opacity,0.f,1.f));if(!f.lights.empty()){const auto&l=f.lights.front();if(ld>=0)a.Uniform3f(ld,l.direction.x,l.direction.y,l.direction.z);if(lc>=0)a.Uniform3f(lc,l.color.r,l.color.g,l.color.b);if(li>=0)a.Uniform1f(li,l.intensity);}}
