bool OpenGLESRenderer::compile_shader(GlEnum type,const char*s,GlUInt&o,std::string&e){o=api_.CreateShader(type);if(!o){e="shader allocation failed";return false;}GlInt n=(GlInt)std::strlen(s);api_.ShaderSource(o,1,&s,&n);api_.CompileShader(o);GlInt ok=0;api_.GetShaderiv(o,COMPILE,&ok);if(ok)return true;GlInt ln=0,w=0;api_.GetShaderiv(o,LOG,&ln);std::vector<char>log((std::size_t)std::max(1,ln));api_.GetShaderInfoLog(o,ln,&w,log.data());e.assign(log.data(),(std::size_t)std::max(0,w));api_.DeleteShader(o);o=0;return false;}
bool OpenGLESRenderer::link_program(const char*,GlUInt v,const char*fs,GlUInt&o,std::string&e){GlUInt f=0;if(!compile_shader(FS,fs,f,e)){if(v)api_.DeleteShader(v);return false;}o=api_.CreateProgram();if(!o){api_.DeleteShader(v);api_.DeleteShader(f);e="program allocation failed";return false;}api_.AttachShader(o,v);api_.AttachShader(o,f);api_.LinkProgram(o);api_.DeleteShader(v);api_.DeleteShader(f);GlInt ok=0;api_.GetProgramiv(o,LINK,&ok);if(ok)return true;GlInt ln=0,w=0;api_.GetProgramiv(o,LOG,&ln);std::vector<char>log((std::size_t)std::max(1,ln));api_.GetProgramInfoLog(o,ln,&w,log.data());e.assign(log.data(),(std::size_t)std::max(0,w));api_.DeleteProgram(o);o=0;return false;}
